import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_svg/flutter_svg.dart';

import '../../db/isar/main_db.dart';
import '../../models/isar/models/isar_models.dart';
import '../../providers/global/wallets_provider.dart';
import '../../themes/stack_colors.dart';
import '../../utilities/amount/amount.dart';
import '../../utilities/amount/amount_formatter.dart';
import '../../utilities/assets.dart';
import '../../utilities/constants.dart';
import '../../utilities/text_styles.dart';
import '../../wallets/isar/providers/wallet_info_provider.dart';
import '../../wallets/wallet/wallet.dart';
import '../../widgets/conditional_parent.dart';
import '../../widgets/icon_widgets/utxo_status_icon.dart';
import '../../widgets/rounded_container.dart';

class UtxoCard extends ConsumerStatefulWidget {
  const UtxoCard({
    super.key,
    required this.utxo,
    required this.walletId,
    required this.onSelectedChanged,
    required this.initialSelectedState,
    required this.canSelect,
    this.onPressed,
  });

  final String walletId;
  final UTXO utxo;
  final void Function(bool) onSelectedChanged;
  final bool initialSelectedState;
  final VoidCallback? onPressed;
  final bool canSelect;

  @override
  ConsumerState<UtxoCard> createState() => _UtxoCardState();
}

class _UtxoCardState extends ConsumerState<UtxoCard> {
  late Stream<UTXO?> stream;
  late UTXO utxo;

  late bool _selected;

  bool _isConfirmed(UTXO utxo, int currentChainHeight, Wallet wallet) {
    return utxo.isConfirmed(
      currentChainHeight,
      wallet.cryptoCurrency.minConfirms,
      wallet.cryptoCurrency.minCoinbaseConfirms,
    );
  }

  @override
  void initState() {
    _selected = widget.initialSelectedState;
    utxo = widget.utxo;

    stream = MainDB.instance.watchUTXO(id: utxo.id);
    super.initState();
  }

  void _toggle() {
    _selected = !_selected;
    widget.onSelectedChanged(_selected);
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");

    final coin = ref.watch(pWalletCoin(widget.walletId));
    final currentHeight = ref.watch(pWalletChainHeight(widget.walletId));

    // Tapping the card selects it (when selectable); details open from
    // the chevron or a long press.
    return ConditionalParent(
      condition: widget.onPressed != null || widget.canSelect,
      builder: (child) => MaterialButton(
        padding: const EdgeInsets.all(0),
        materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
        color: Theme.of(context).extension<StackColors>()!.popupBG,
        elevation: 0,
        disabledElevation: 0,
        hoverElevation: 0,
        focusElevation: 0,
        highlightElevation: 0,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(
            Constants.size.circularBorderRadius,
          ),
        ),
        onPressed: widget.canSelect ? _toggle : widget.onPressed,
        onLongPress: widget.onPressed,
        child: child,
      ),
      child: RoundedContainer(
        color: widget.onPressed == null && !widget.canSelect
            ? Theme.of(context).extension<StackColors>()!.popupBG
            : Colors.transparent,
        child: StreamBuilder<UTXO?>(
          stream: stream,
          builder: (context, snapshot) {
            if (snapshot.hasData) {
              utxo = snapshot.data!;
            }
            return Row(
              children: [
                ConditionalParent(
                  condition: widget.canSelect,
                  builder: (child) =>
                      GestureDetector(onTap: _toggle, child: child),
                  child: UTXOStatusIcon(
                    blocked: utxo.isBlocked,
                    status:
                        _isConfirmed(
                          utxo,
                          currentHeight,
                          ref.watch(
                            pWallets.select(
                              (s) => s.getWallet(widget.walletId),
                            ),
                          ),
                        )
                        ? UTXOStatusIconStatus.confirmed
                        : UTXOStatusIconStatus.unconfirmed,
                    background: Theme.of(context)
                        .extension<StackColors>()!
                        .popupBG,
                    selected: _selected,
                    width: 32,
                    height: 32,
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        ref
                            .watch(pAmountFormatter(coin))
                            .format(
                              utxo.value.toAmountAsRaw(
                                fractionDigits: coin.fractionDigits,
                              ),
                            ),
                        style: STextStyles.w600_14(context),
                      ),
                      const SizedBox(height: 2),
                      Row(
                        children: [
                          Flexible(
                            child: Text(
                              utxo.name.isNotEmpty
                                  ? utxo.name
                                  : utxo.address ?? utxo.txid,
                              style: STextStyles.w500_12(context).copyWith(
                                color: Theme.of(context)
                                    .extension<StackColors>()!
                                    .textSubtitle1,
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 2),
                      Builder(
                        builder: (context) {
                          final confirmations = utxo.getConfirmations(
                            currentHeight,
                          );
                          return Text(
                            "$confirmations confirmation"
                            "${confirmations == 1 ? "" : "s"}",
                            style: STextStyles.w500_12(context).copyWith(
                              color: Theme.of(context)
                                  .extension<StackColors>()!
                                  .textSubtitle1,
                            ),
                          );
                        },
                      ),
                    ],
                  ),
                ),
                if (widget.onPressed != null)
                  GestureDetector(
                    onTap: widget.onPressed,
                    child: Padding(
                      padding: const EdgeInsets.only(left: 10),
                      child: SvgPicture.asset(
                        Assets.svg.chevronRight,
                        width: 20,
                        height: 20,
                        colorFilter: ColorFilter.mode(
                          Theme.of(context)
                              .extension<StackColors>()!
                              .textSubtitle1,
                          BlendMode.srcIn,
                        ),
                      ),
                    ),
                  ),
              ],
            );
          },
        ),
      ),
    );
  }
}
